"""The Grader: reduces N model candidate outputs down to 1.

Hybrid evaluation:
1. Deterministic filter: Disqualifies errors, crashes, and empty text.
   If only one candidate survives, return it immediately (zero tokens spent).
2. Semantic judge: Prompts a model to compare the survivors, parse the winning
   number, and return the winning ModelCompleted.
"""
from __future__ import annotations

import re
from typing import Any, Callable

from .types import CallModel, ModelCompleted


def is_clean(candidate: ModelCompleted) -> bool:
    """True if the candidate returned meaningful text or tool calls without an error."""
    text = (candidate.text or "").strip()
    if not text and not candidate.tool_calls:
        return False
    if text.startswith("error:") or text.startswith("(no answer:"):
        return False
    return True


class Judge:
    """A callable reducer for ParFold: candidates -> winning ModelCompleted."""

    def __init__(
        self,
        wire: Any = None,
        task: str = "",
        fallback: Callable[[list[ModelCompleted]], ModelCompleted] | None = None,
    ):
        self.wire = wire
        self.task = task
        self.fallback = fallback or (lambda cs: cs[0])

    def __call__(self, candidates: list[ModelCompleted]) -> ModelCompleted:
        if not candidates:
            return ModelCompleted(text="error: no candidates to judge", tool_calls=[], usage={})

        # 1. Deterministic layer: filter out errors and empty answers
        survivors = [(i + 1, c) for i, c in enumerate(candidates) if is_clean(c)]

        if not survivors:
            # Everything failed; fallback to whatever we have
            return self.fallback(candidates)

        if len(survivors) == 1:
            # Only one clean candidate survived; no need to spend judge tokens
            return survivors[0][1]

        if self.wire is None:
            # No model wire provided; fallback deterministically (e.g. first clean)
            return survivors[0][1]

        # 2. Semantic layer: ask the judge model to pick the best
        prompt = self._build_prompt(survivors)
        effect = CallModel(
            system="You are an impartial judge. Compare the candidates and pick the best one.",
            tools=[],
            messages=[{"role": "user", "content": prompt}],
        )

        try:
            decision = self.wire.call(effect)
            pick_idx = self._parse_pick(decision.text, len(candidates))
            if pick_idx is not None:
                return candidates[pick_idx]
        except Exception:
            pass

        return survivors[0][1]

    def _build_prompt(self, survivors: list[tuple[int, ModelCompleted]]) -> str:
        blocks = [f"Original task:\n{self.task or '(unspecified task)'}\n"]
        for num, c in survivors:
            content = c.text
            if c.tool_calls:
                tool_names = ", ".join(call["name"] for call in c.tool_calls)
                content = f"[tool calls: {tool_names}]\n{content}"
            blocks.append(f"--- Candidate {num} ---\n{content}")
        blocks.append(
            "Which candidate is best? Reply strictly in this format:\n"
            "WINNER: <number>\n"
            "REASON: <one sentence justification>"
        )
        return "\n\n".join(blocks)

    def _parse_pick(self, text: str, total: int) -> int | None:
        """Extract 0-indexed candidate index from 'WINNER: X' or first valid digit."""
        match = re.search(r"WINNER:\s*(\d+)", text, re.IGNORECASE)
        if match:
            idx = int(match.group(1)) - 1
            if 0 <= idx < total:
                return idx
        # Fallback search for any digit matching candidate numbers
        for digit in re.findall(r"\b(\d+)\b", text):
            idx = int(digit) - 1
            if 0 <= idx < total:
                return idx
        return None

"""Wire: the plug behind the Model seam, for Anthropic.

Takes the payload and a seat id. Asks the seat table for the URL and key.
Writes the provider's JSON. Sends it. Reads the reply back into a
ModelCompleted event. That is all a wire does.

This is the only code in the package that knows what Anthropic's request
looks like. If cache breakpoints ever matter, this is the only file that
would write them. Naive version: one urllib call, no retries, no streaming.
"""
from __future__ import annotations

import json
import os
import urllib.request

from . import seats
from .types import CallModel, ModelCompleted


class AnthropicWire:
    def __init__(self, seat_id: str, model: str, effort: str | None = None):
        self.seat = seats.lookup(seat_id)
        self.model = model
        self.effort = effort

    def call(self, effect: CallModel) -> ModelCompleted:
        body = {
            "model": self.model,
            "max_tokens": effect.max_tokens or 16000,
            "system": effect.system,
            "tools": [_tool(t) for t in effect.tools],
            "messages": [_message(m) for m in effect.messages],
        }
        if self.effort:
            body["output_config"] = {"effort": self.effort}
        request = urllib.request.Request(
            self.seat.url,
            data=json.dumps(body).encode(),
            headers={
                "content-type": "application/json",
                "x-api-key": os.environ[self.seat.key_env],
                "anthropic-version": "2023-06-01",
            },
        )
        with urllib.request.urlopen(request) as response:
            reply = json.load(response)

        seats.spend(self.seat.id, reply["usage"]["output_tokens"] / 1_000_000)
        return _completed(reply)


# --- the two directions of translation ---------------------------------------

def _tool(schema: dict) -> dict:
    """Our tool schema is already the Anthropic shape: name, description, input_schema."""
    return schema


def _message(m: dict) -> dict:
    """Our messages are OpenAI-shaped. Anthropic wants tool results as user content blocks."""
    if m["role"] == "tool":
        return {"role": "user", "content": [
            {"type": "tool_result", "tool_use_id": m["tool_call_id"], "content": m["content"]}]}
    if m["role"] == "assistant" and m.get("tool_calls"):
        blocks = [{"type": "text", "text": m["content"]}] if m["content"] else []
        blocks += [{"type": "tool_use", "id": c["id"], "name": c["name"], "input": c["arguments"]}
                   for c in m["tool_calls"]]
        return {"role": "assistant", "content": blocks}
    return {"role": m["role"], "content": m["content"]}


def _completed(reply: dict) -> ModelCompleted:
    text = "".join(b["text"] for b in reply["content"] if b["type"] == "text")
    calls = [{"id": b["id"], "name": b["name"], "arguments": b["input"]}
             for b in reply["content"] if b["type"] == "tool_use"]
    return ModelCompleted(text=text, tool_calls=calls, usage=reply["usage"])

"""Wire: the plug behind the Model seam, for anything OpenAI-shaped.

OpenAI, xAI, Gemini's compatibility endpoint, a local server: all take the
same request. The seat's URL says where. Same contract as wire_anthropic.py:
payload and seat in, ModelCompleted out.
"""
from __future__ import annotations

import json
import os
import urllib.request

from . import seats
from .types import CallModel, ModelCompleted


class OpenAIWire:
    def __init__(self, seat_id: str, model: str, effort: str | None = None):
        self.seat = seats.lookup(seat_id)
        self.model = model
        self.effort = effort

    def call(self, effect: CallModel) -> ModelCompleted:
        body = {
            "model": self.model,
            "messages": [{"role": "system", "content": effect.system}] + _format_messages(effect.messages),
        }
        if effect.tools:
            body["tools"] = [_tool(t) for t in effect.tools]
        if effect.max_tokens:
            body["max_tokens"] = effect.max_tokens
        if self.effort:
            body["reasoning_effort"] = self.effort

        request = urllib.request.Request(
            self.seat.url,
            data=json.dumps(body).encode(),
            headers={
                "content-type": "application/json",
                "authorization": f"Bearer {os.environ[self.seat.key_env]}",
                "user-agent": "Arity/1.0",
            },
        )
        try:
            with urllib.request.urlopen(request) as response:
                reply = json.load(response)
        except urllib.error.HTTPError as e:
            error_body = e.read().decode(errors="replace")
            raise RuntimeError(f"HTTP {e.code} from {self.seat.url} for model {self.model}: {error_body}") from e
        usage = reply.get("usage") or {}
        tokens = usage.get("completion_tokens") or 0
        seats.spend(self.seat.id, tokens / 1_000_000)
        return _completed(reply)

def _format_message(m: dict) -> dict:
    msg = dict(m)
    if "tool_calls" in msg and msg["tool_calls"]:
        formatted = []
        for c in msg["tool_calls"]:
            if "function" in c:
                formatted.append(c)
            else:
                args = c.get("arguments", "{}")
                if isinstance(args, dict):
                    args = json.dumps(args)
                formatted.append({
                    "id": c.get("id") or "call_0",
                    "type": "function",
                    "function": {
                        "name": c.get("name", ""),
                        "arguments": args,
                    },
                })
        msg["tool_calls"] = formatted
    return msg


def _format_messages(messages: list[dict]) -> list[dict]:
    formatted = []
    i = 0
    while i < len(messages):
        msg = _format_message(messages[i])
        formatted.append(msg)

        if msg.get("role") == "assistant" and msg.get("tool_calls"):
            expected_ids = {c["id"]: c.get("function", {}).get("name", "tool")
                            for c in msg["tool_calls"] if "id" in c}
            j = i + 1
            while j < len(messages) and messages[j].get("role") == "tool":
                tool_msg = _format_message(messages[j])
                formatted.append(tool_msg)
                expected_ids.pop(tool_msg.get("tool_call_id"), None)
                j += 1
            for missing_id, tool_name in expected_ids.items():
                formatted.append({
                    "role": "tool",
                    "tool_call_id": missing_id,
                    "name": tool_name,
                    "content": "(no tool output / interrupted)",
                })
            i = j
        else:
            i += 1

    return formatted


def _tool(schema: dict) -> dict:
    """OpenAI wraps the same three fields in {"type": "function", "function": {...}}."""
    return {"type": "function", "function": {
        "name": schema["name"],
        "description": schema["description"],
        "parameters": schema["input_schema"],
    }}


def _completed(reply: dict) -> ModelCompleted:
    message = reply["choices"][0]["message"]
    calls = [{"id": c.get("id") or "call_0", "name": c["function"]["name"], "arguments": c["function"]["arguments"]}
             for c in message.get("tool_calls") or []]
    return ModelCompleted(text=message.get("content") or "", tool_calls=calls, usage=reply.get("usage") or {})
